SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 2016 AND 2017 AND p.anchor_age BETWEEN 52 AND 62 AND d.icd_code IN ('23044007', '23044008') AND e.infusion_type = 'IV' THEN e.orderid END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.orderid), 0) AS proportion_of_orders_in_first_24_hours, CAST(COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 2016 AND 2017 AND p.anchor_age BETWEEN 52 AND 62 AND d.icd_code IN ('23044007', '23044008') AND e.infusion_type = 'IV' THEN e.orderid END) AS FLOAT) / NULLIF(COUNT(DISTINCT e.orderid), 0) AS proportion_of_orders_in_last_48_hours, (proportion_of_orders_in_last_48_hours - proportion_of_orders_in_first_24_hours) / NULLIF(proportion_of_orders_in_first_24_hours, 0) AS relative_change FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN emar e ON a.subject_id = e.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 2016 AND 2017 AND p.anchor_age BETWEEN 52 AND 62 AND d.icd_code IN ('23044007', '23044008') AND e.infusion_type = 'IV';